namespace sv_929af6bad2774f60a15de14e79bf1d6c.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit in Interactive Server mode.
/// All interactive components in the same circuit share this instance.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        NotifyStateChanged();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        NotifyStateChanged();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
        NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@using sv_929af6bad2774f60a15de14e79bf1d6c.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;">
    @GetIcon() @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += StateHasChanged;
    }

    private string GetIcon() => ThemeSvc.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeSvc.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@using sv_929af6bad2774f60a15de14e79bf1d6c.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width:200px"
            value="@ThemeSvc.Theme"
            @onchange="OnThemeChanged">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeSvc.AccentColor"
           @onchange="OnColorChanged" />
</div>

<p>
    Current: <strong style="color: @ThemeSvc.AccentColor;">@ThemeSvc.Theme</strong>
</p>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += StateHasChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeSvc.SetTheme(mode);
        }
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeSvc.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= StateHasChanged;
    }
}

